-- Supabase/PostgreSQL schema and data for vehicles
create table if not exists public.vehicles (
  id bigint generated by default as identity primary key,
  vehicle_id varchar(50) not null unique,
  name varchar(255) not null,
  type varchar(100) not null,
  main_category varchar(50) not null,
  price numeric(10,2) not null,
  sr_points integer not null default 0,
  image text,
  description text,
  features jsonb,
  transmission varchar(50) default 'Automatic',
  fuel varchar(50) default 'Gasoline',
  seats integer default 5,
  status text not null default 'available' check (status in ('available', 'booked', 'maintenance', 'archived')),
  is_featured boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists idx_vehicle_type on public.vehicles (type);
create index if not exists idx_vehicle_status on public.vehicles (status);
create index if not exists idx_main_category on public.vehicles (main_category);
create index if not exists idx_featured on public.vehicles (is_featured);

create or replace function public.set_vehicles_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

drop trigger if exists trg_vehicles_updated_at on public.vehicles;
create trigger trg_vehicles_updated_at
before update on public.vehicles
for each row execute function public.set_vehicles_updated_at();

